async function getJobQueueStats() {
  const res = await pool.query(
    `SELECT job_type, status, COUNT(*)::text AS cnt
     FROM kf.search_index_jobs
     WHERE status IN ('QUEUED', 'RUNNING', 'FAILED')
     GROUP BY job_type, status`
  ).catch(() => ({ rows: [] }));
  const stats = { queuedRebuildJobs: 0, queuedReembedJobs: 0, runningJobs: 0, failedJobs: 0 };
  for (const row of res.rows) {
    const cnt = parseInt(row.cnt, 10);
    if (row.status === "QUEUED" && row.job_type === "REBUILD_INDEX") stats.queuedRebuildJobs += cnt;
    if (row.status === "QUEUED" && row.job_type === "REEMBED") stats.queuedReembedJobs += cnt;
    if (row.status === "RUNNING") stats.runningJobs += cnt;
    if (row.status === "FAILED") stats.failedJobs += cnt;
  }
  return stats;
}
