async function getKfV2BatchObservability(batchId) {
  const result = await pool.query(
    `SELECT b.id, b.stage, b.status, b.worker_id, b.attempt, b.success_count,
            b.failed_count, b.started_at, b.heartbeat_at, b.completed_at,
            b.updated_at, w.last_heartbeat AS worker_heartbeat,
            CASE WHEN b.failed_count > 0 THEN 'BATCH_ITEMS_FAILED' ELSE NULL END AS failure_reason,
            count(i.id)::text AS total_items,
            count(i.id) FILTER (WHERE i.status='RUNNING')::text AS running,
            count(i.id) FILTER (WHERE i.status IN ('PENDING','PARTIAL'))::text AS pending
       FROM kf.ingestion_batches b
       LEFT JOIN kf.ingestion_batch_items i ON i.batch_id=b.id
       LEFT JOIN kf.worker_heartbeats w ON w.worker_id=b.worker_id
      WHERE b.id=$1
       GROUP BY b.id, w.last_heartbeat`,
    [batchId]
  );
  const row = result.rows[0];
  if (!row) return null;
  const workerPresent = Boolean(row.worker_id);
  return {
    batch_id: row.id,
    stage: row.stage,
    status: row.status,
    lifecycle_status: classifyKfV2Lifecycle({
      status: row.status,
      lastProgressAt: row.updated_at,
      heartbeatAt: row.worker_heartbeat ?? row.heartbeat_at,
      workerPresent
    }),
    worker: row.worker_id,
    attempt: row.attempt,
    total_items: Number(row.total_items),
    success: row.success_count,
    failed: row.failed_count,
    running: Number(row.running),
    pending: Number(row.pending),
    started_at: row.started_at,
    last_progress_at: row.updated_at,
    heartbeat_at: row.worker_heartbeat ?? row.heartbeat_at,
    completed_at: row.completed_at,
    failure_reason: row.failure_reason
  };
}
async function getKfV2FailedItemObservability(filters) {
  const values = [];
  const predicates = [];
  for (const [key, value] of [
    ["document_id", filters.documentId],
    ["stage", filters.stage],
    ["status", filters.status],
    ["failure_code", filters.failureCode]
  ]) {
    if (value) {
      values.push(value);
      predicates.push(`${key}=$${values.length}`);
    }
  }
  const result = await pool.query(
    `SELECT id, source_reference, failure_reason, paid_attempt, manual_retry_count,
            status, document_id, stage, failure_code
       FROM kf.failed_items
      ${predicates.length ? `WHERE ${predicates.join(" AND ")}` : ""}
      ORDER BY last_failed_at DESC
      LIMIT 200`,
    values
  );
  return result.rows.map((row) => ({
    failed_item_id: row.id,
    document_id: row.document_id,
    stage: row.stage,
    failure_code: row.failure_code,
    source_reference: row.source_reference,
    failure_reason: row.failure_reason,
    paid_attempt: row.paid_attempt,
    manual_retry_count: row.manual_retry_count,
    status: row.status
  }));
}
async function getKfV2Health() {
  let dbReady = false;
  let recentHeartbeat = false;
  try {
    await pool.query("SELECT 1");
    dbReady = true;
    const heartbeat = await pool.query(
      `SELECT count(*)::text AS count
         FROM kf.worker_heartbeats
        WHERE status <> 'OFFLINE'
          AND last_heartbeat >= now() - ($1 * interval '1 millisecond')`,
      [Number(process.env.KF_V2_HEARTBEAT_STALE_MS ?? DEFAULT_STALE_MS)]
    );
    recentHeartbeat = Number(heartbeat.rows[0]?.count ?? 0) > 0;
  } catch {
    dbReady = false;
    recentHeartbeat = false;
  }
  const r2Configured = [
    "CF_ACCOUNT_ID",
    "CF_R2_ACCESS_KEY_ID",
    "CF_R2_SECRET_ACCESS_KEY",
    "CF_R2_BUCKET_NAME"
  ].every((key) => Boolean(process.env[key])) && process.env.KF_V2_STORAGE_PROVIDER === "r2" && process.env.KF_V2_USE_REPLIT_FALLBACK !== "true";
  const openAiConfigured = Boolean(process.env.OPENAI_API_KEY) && process.env.KF_V2_OPENAI_PROVIDER === "direct";
  return {
    db_ready: dbReady,
    queue_ready: process.env.KF_V2_QUEUE_READY === "true",
    worker_recent_heartbeat: recentHeartbeat,
    r2_configured: r2Configured,
    openai_configured: openAiConfigured,
    v2_runtime_enabled: process.env.KF_INGESTION_V2_ENABLED === "true"
  };
}

