          const isDup = score >= THRESHOLD_NEAR;
          if (!bestMatch || score > bestMatch.similarityScore) {
            bestMatch = {
              existingId: k.id,
              existingType: "knowledge",
              similarityScore: score,
              duplicateType: dupType,
              isDuplicate: isDup
            };
          }
