// src/lib/conflict-detection.ts
init_drizzle_orm();
init_src();
var THRESHOLD_CONFLICT_SIMILARITY = 0.7;
var NEGATION_PATTERNS = [
  /안\s*(?:된|되|해야|한다|좋)/,
  /하지\s*않/,
  /않\s*(?:는|아야|아도|아서)/,
  /금지/,
  /위험/,
  /피해야/,
  /해서는\s*안/,
  /\bnot\b/i,
  /\bnever\b/i,
  /\bavoid\b/i,
  /\bdo\s+not\b/i,
  /\bshould\s+not\b/i,
  /\bmust\s+not\b/i,
  /\bincorrect\b/i,
  /\bwrong\b/i,
  /\bfalse\b/i
];
function hasNegationSignal(text7) {
  return NEGATION_PATTERNS.some((p) => p.test(text7));
}
function detectContradiction(candidateText, existingText) {
  const score = jaccardSimilarity2(candidateText, existingText);
  if (score < THRESHOLD_CONFLICT_SIMILARITY) {
    return { conflictType: "NONE", similarityScore: score };
  }
  const candidateNeg = hasNegationSignal(candidateText);
  const existingNeg = hasNegationSignal(existingText);
  if (candidateNeg !== existingNeg) {
    return { conflictType: "CONTRADICTION", similarityScore: score };
  }
  return { conflictType: "OVERLAP", similarityScore: score };
}
async function runConflictCheck(importCandidateId, organizationId, actorId) {
  const candidateResult = await findImportCandidateById(importCandidateId, organizationId);
  if (!candidateResult.ok) {
    return { ok: false, code: "NOT_FOUND", message: `\uD6C4\uBCF4\uB97C \uCC3E\uC744 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4: ${importCandidateId}` };
  }
  const candidate = candidateResult.data;
  const candidateContent = candidate["normalizedContent"] ?? candidate.rawContent ?? "";
  let bestConflict = null;
  if (candidateContent) {
    try {
      const knowledgeRows = await db.select({ id: knowledge.id, content: knowledge.content }).from(knowledge).where(eq(knowledge.organizationId, organizationId)).limit(200);
      for (const k of knowledgeRows) {
        if (!k.content) continue;
        const { conflictType, similarityScore } = detectContradiction(candidateContent, k.content);
        if (conflictType === "NONE") continue;
        const requiresAdminReview = conflictType === "CONTRADICTION";
        const description = conflictType === "CONTRADICTION" ? `\uC720\uC0AC \uC8FC\uC81C(${(similarityScore * 100).toFixed(0)}%)\uC5D0\uC11C \uC0C1\uCDA9\uB418\uB294 \uC8FC\uC7A5\uC774 \uAC10\uC9C0\uB418\uC5C8\uC2B5\uB2C8\uB2E4.` : `\uC720\uC0AC \uB0B4\uC6A9(${(similarityScore * 100).toFixed(0)}%)\uACFC \uACB9\uCE58\uB294 \uBD80\uBD84\uC774 \uC788\uC2B5\uB2C8\uB2E4.`;
        if (!bestConflict || similarityScore > bestConflict.contradictionScore) {
          bestConflict = {
            existingKnowledgeId: k.id,
            conflictType,
            contradictionScore: similarityScore,
            description,
            requiresAdminReview
          };
        }
        if (conflictType === "CONTRADICTION") break;
      }
    } catch (_e) {
    }
  }
  const hasConflict = bestConflict !== null;
  const recordResult = await recordConflictCheck(
    {
      importCandidateId,
      conflictingKnowledgeId: bestConflict?.existingKnowledgeId,
      conflictType: bestConflict?.conflictType,
      contradictionScore: bestConflict?.contradictionScore,
      description: bestConflict?.description,
      autoResolvable: !bestConflict?.requiresAdminReview,
      requiresAdminReview: bestConflict?.requiresAdminReview ?? false,
      modelProvider: "STEP07_HEURISTIC",
      modelName: "negation-heuristic-v1"
    },
    { organizationId, actorId }
  );
  if (!recordResult.ok) {
    return { ok: false, code: "INTERNAL", message: "\uCDA9\uB3CC \uAC80\uC0AC \uACB0\uACFC \uC800\uC7A5 \uC2E4\uD328" };
  }
  return {
    ok: true,
    data: {
      importCandidateId,
      bestConflict,
      hasConflict,
      record: recordResult.data
    }
  };
}

// src/lib/review-orchestrator.ts
init_logger2();
async function runChecksAndEnqueue(importCandidateId, organizationId, actorId) {
  const candidateResult = await findImportCandidateById(importCandidateId, organizationId);
  if (!candidateResult.ok) {
    return { ok: false, code: "NOT_FOUND", message: `\uD6C4\uBCF4\uB97C \uCC3E\uC744 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4: ${importCandidateId}` };
  }
  const candidate = candidateResult.data;
  const dupResult = await runDuplicateCheck(importCandidateId, organizationId, actorId);
  if (!dupResult.ok) {
    return { ok: false, code: dupResult.code, message: `\uC911\uBCF5 \uAC80\uC0AC \uC2E4\uD328: ${dupResult.message}` };
  }
  const confResult = await runConflictCheck(importCandidateId, organizationId, actorId);
  if (!confResult.ok) {
    return { ok: false, code: confResult.code, message: `\uCDA9\uB3CC \uAC80\uC0AC \uC2E4\uD328: ${confResult.message}` };
  }
  await updateImportCandidate(importCandidateId, organizationId, {
    candidateStatus: "REVIEWING"
  });
  const flags = [];
  if (dupResult.data.isDuplicate) flags.push(`\uC911\uBCF5(${dupResult.data.bestMatch?.duplicateType})`);
  if (confResult.data.hasConflict) flags.push(`\uCDA9\uB3CC(${confResult.data.bestConflict?.conflictType})`);
  const needsReview = flags.length > 0;
  const reviewReason = needsReview ? `\uC790\uB3D9 \uAC80\uC0AC \uC774\uC288 \uAC10\uC9C0: ${flags.join(", ")}` : "\uD45C\uC900 \uC778\uAC04 \uAC80\uD1A0 \uC808\uCC28";
  const queuePriority = needsReview ? 1 : 5;
  const flagCodes = [];
  if (dupResult.data.isDuplicate) flagCodes.push("DUPLICATE");
  if (confResult.data.bestConflict?.conflictType === "CONTRADICTION") flagCodes.push("CONTRADICTION");
  else if (confResult.data.bestConflict?.conflictType === "OVERLAP") flagCodes.push("OVERLAP");
  const enqueueResult = await enqueueForReview(
    {
      importJobId: candidate.importJobId ?? "",
      importCandidateId,
      queuePriority,
      reviewReason,
      flagCodes
    },
    { organizationId, actorId }
  );
  if (!enqueueResult.ok) {
    logger.warn({ importCandidateId, error: enqueueResult.error }, "\uD050 \uB4F1\uB85D \uC2E4\uD328 (\uAC80\uC0AC \uACB0\uACFC\uB294 \uC800\uC7A5\uB428)");
    return {
      ok: true,
      data: {
        importCandidateId,
        duplicateCheck: dupResult.data,
        conflictCheck: confResult.data,
        needsReview,
        reviewReason,
        reviewQueueId: null
      }
    };
  }
  return {
    ok: true,
    data: {
      importCandidateId,
      duplicateCheck: dupResult.data,
      conflictCheck: confResult.data,
      needsReview,
      reviewReason,
      reviewQueueId: enqueueResult.data.id
    }
  };
}
async function processDecision(organizationId, input) {
  const { importCandidateId, decision, decisionReason, modifiedContent, decidedBy, reviewQueueId } = input;
  const candidateResult = await findImportCandidateById(importCandidateId, organizationId);
  if (!candidateResult.ok) {
    return { ok: false, code: "NOT_FOUND", message: `\uD6C4\uBCF4\uB97C \uCC3E\uC744 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4: ${importCandidateId}` };
  }
  const candidate = candidateResult.data;
  const statusMap = {
    APPROVE: "APPROVED",
    REJECT: "REJECTED",
    DEFER: "REVIEWING",
    MERGE: "MERGED",
    MODIFY: "REVIEWING"
  };
  const newCandidateStatus = statusMap[decision] ?? "REVIEWING";
  const decisionRecord = await recordReviewDecision(
    {
      importCandidateId,
      reviewQueueId,
      decision,
      decisionReason,
      modifiedContent,
      decidedBy
    },
    { organizationId }
  );
  if (!decisionRecord.ok) {
    return { ok: false, code: "INTERNAL", message: "\uACB0\uC815 \uAE30\uB85D \uC2E4\uD328" };
  }
  const updatePayload = { candidateStatus: newCandidateStatus };
  if (decision === "MODIFY" && modifiedContent) {
    updatePayload["rawContent"] = modifiedContent;
  }
  await updateImportCandidate(importCandidateId, organizationId, updatePayload);
  if (decision === "REJECT") {
    await recordRejection(
      {
        importCandidateId,
        importJobId: candidate.importJobId ?? "",
        rejectionCode: input.rejectionCode ?? "MANUAL_REJECT",
        rejectionReason: decisionReason ?? "\uAD00\uB9AC\uC790\uC5D0 \uC758\uD574 \uAC70\uBD80\uB428",
        isAutomated: false,
        rejectedBy: decidedBy
      },
      { organizationId }
    );
  }
  if (decision === "MERGE" && input.mergeTargetKnowledgeId) {
    await registerMergeCandidate(
      organizationId,
      input.mergeTargetKnowledgeId,
      importCandidateId,
      1
    );
  }
  let queueCompleted = false;
  if (reviewQueueId && decision !== "DEFER" && decision !== "MODIFY") {
    const completeResult = await completeReviewItem(reviewQueueId, organizationId);
    queueCompleted = completeResult.ok;
  }
  return {
    ok: true,
    data: {
      importCandidateId,
      decision,
      newCandidateStatus,
      queueCompleted
    }
  };
}

