// src/lib/calibration-provider.ts
async function getCalibrationMeta(orgId, feedbackType, sessionId) {
  try {
    const rows = await db.select().from(feedbackScoreSummary).where(
      and(
        eq(feedbackScoreSummary.organizationId, orgId),
        eq(feedbackScoreSummary.feedbackType, feedbackType)
      )
    ).limit(1);
    if (rows.length === 0) {
      return {
        adjustmentFactor: null,
        insufficientData: false,
        wasCalibrated: false,
        status: "SUMMARY_NOT_FOUND",
        computedAt: null
      };
    }
    const row = rows[0];
    if (row.insufficientData) {
      return {
        adjustmentFactor: null,
        insufficientData: true,
        wasCalibrated: false,
        status: "INSUFFICIENT_DATA",
        computedAt: row.computedAt
      };
    }
    if (row.adjustmentFactor === null || row.adjustmentFactor === void 0) {
      return {
        adjustmentFactor: null,
        insufficientData: false,
        wasCalibrated: false,
        status: "FACTOR_UNAVAILABLE",
        computedAt: row.computedAt
      };
    }
    const factor = Number(row.adjustmentFactor);
    if (!isFinite(factor) || isNaN(factor)) {
      return {
        adjustmentFactor: null,
        insufficientData: false,
        wasCalibrated: false,
        status: "FACTOR_UNAVAILABLE",
        computedAt: row.computedAt
      };
    }
    return {
      adjustmentFactor: factor,
      insufficientData: false,
      wasCalibrated: true,
      status: "APPLIED",
      computedAt: row.computedAt
    };
  } catch (_err) {
    return {
      adjustmentFactor: null,
      insufficientData: false,
      wasCalibrated: false,
      status: "PROVIDER_ERROR",
      computedAt: null
    };
  }
}
function applyCalibration(rawScore, meta) {
  if (!meta.wasCalibrated || meta.adjustmentFactor === null) {
    return rawScore;
  }
  const result = rawScore * meta.adjustmentFactor;
  return Math.min(1, Math.max(0, result));
}
function buildCalibratedConfidenceResponse(params) {
  const { rawScore, meta, organizationId, feedbackType, sessionId } = params;
  if (isNaN(rawScore) || !isFinite(rawScore)) {
    logger.error({
      event: "calibration_raw_score_invalid",
      organizationId,
      feedbackType,
      sessionId,
      rawScore
    });
    return {
      confidenceScore: 0,
      rawConfidenceScore: 0,
      calibration: {
        adjustmentFactor: null,
        status: "INTERNAL",
        computedAt: null,
        wasCalibrated: false,
        insufficientData: false
      }
    };
  }
  if (meta.status === "PROVIDER_ERROR") {
    logger.error({
      event: "calibration_provider_error",
      organizationId,
      feedbackType,
      sessionId
    });
  }
  if (meta.status === "FACTOR_UNAVAILABLE") {
    logger.warn({
      event: "calibration_factor_unavailable",
      organizationId,
      feedbackType,
      sessionId,
      adjustmentFactor: meta.adjustmentFactor
    });
  }
  const calibratedScore = applyCalibration(rawScore, meta);
  return {
    confidenceScore: calibratedScore,
    rawConfidenceScore: rawScore,
    calibration: {
      adjustmentFactor: meta.adjustmentFactor,
      status: meta.status,
      computedAt: meta.computedAt ? meta.computedAt.toISOString() : null,
      wasCalibrated: meta.wasCalibrated,
      insufficientData: meta.insufficientData
    }
  };
}

