async function runDiagnosis(organizationId, queryText, options = {}) {
  const { requestedBy } = options;
  const ctx = { organizationId };
  const startMs = Date.now();
  const sessionRes = await createReasoningSession(
    { sessionType: "DIAGNOSIS", queryText, requestedBy },
    ctx
  );
  if (!sessionRes.ok) {
    throw new DomainError("INTERNAL", `Failed to create reasoning session: ${sessionRes.error}`);
  }
  const sessionId = sessionRes.data.id;
  let stepOrder = 0;
  let relevanceScores = [];
  let supportingEvidence = [];
  let retrievedKnowledgeIds = [];
  let conflictCount = 0;
  let authorityScores = [];
  let knowledgeUpdatedAts = [];
  const matchedDiagnoses = [];
  stepOrder++;
  const retrieveStart = Date.now();
  const searchRes = await runSemanticSearch(organizationId, queryText, { topK: RETRIEVE_TOP_K });
  retrievedKnowledgeIds = searchRes.items.map((i) => i.knowledgeId);
  relevanceScores = searchRes.items.map((i) => i.score);
  for (const item of searchRes.items) {
    await recordReasoningEvidence({
      sessionId,
      evidenceType: "SUPPORTING",
      knowledgeId: item.knowledgeId,
      relevanceScore: item.score,
      content: item.snippet
    }, ctx);
    supportingEvidence.push({ content: item.snippet, score: item.score });
  }
  await appendReasoningStep({
    sessionId,
    stepType: "RETRIEVE",
    stepOrder,
    notes: `query="${queryText.slice(0, 50)}" topK=${RETRIEVE_TOP_K} retrieved=${retrievedKnowledgeIds.length}`,
    durationMs: Date.now() - retrieveStart
  }, ctx);
  stepOrder++;
  const compareStart = Date.now();
  let diagRows = [];
  if (retrievedKnowledgeIds.length > 0) {
    const relations = await db.select({ diagnosisId: knowledgeDiagnosisRelation.diagnosisId }).from(knowledgeDiagnosisRelation).where(inArray(knowledgeDiagnosisRelation.knowledgeId, retrievedKnowledgeIds));
    const diagnosisIds = [...new Set(relations.map((r) => r.diagnosisId))];
    if (diagnosisIds.length > 0) {
      const rows = await db.select({
        id: diagnosis.id,
        code: diagnosis.code,
        nameKo: diagnosis.nameKo,
        impactScore: diagnosis.impactScore
      }).from(diagnosis).where(
        and(
          inArray(diagnosis.id, diagnosisIds),
          eq(diagnosis.organizationId, organizationId)
        )
      );
      diagRows = rows.filter((r) => (r.impactScore ?? 0) >= DIAGNOSIS_IMPACT_THRESHOLD);
    }
  }
  await appendReasoningStep({
    sessionId,
    stepType: "COMPARE",
    stepOrder,
    notes: `knowledgeIds=${retrievedKnowledgeIds.length} diagCandidates=${diagRows.length}`,
    durationMs: Date.now() - compareStart
  }, ctx);
  stepOrder++;
  const validateStart = Date.now();
  if (retrievedKnowledgeIds.length >= 2) {
    const contradictRelations = await db.select({
      sourceKnowledgeId: knowledgeKnowledgeRelation.sourceKnowledgeId,
      targetKnowledgeId: knowledgeKnowledgeRelation.targetKnowledgeId
    }).from(knowledgeKnowledgeRelation).where(
      and(
        eq(knowledgeKnowledgeRelation.relationType, "CONTRADICTS"),
        inArray(knowledgeKnowledgeRelation.sourceKnowledgeId, retrievedKnowledgeIds),
        inArray(knowledgeKnowledgeRelation.targetKnowledgeId, retrievedKnowledgeIds)
      )
    );
    for (const rel of contradictRelations) {
      conflictCount++;
      await recordReasoningConflict(sessionId, organizationId, {
        conflictType: "KNOWLEDGE_CONTRADICTS",
        knowledgeIdA: rel.sourceKnowledgeId,
        knowledgeIdB: rel.targetKnowledgeId,
        description: `CONTRADICTS: ${rel.sourceKnowledgeId} \u2194 ${rel.targetKnowledgeId}`
      });
    }
  }
  authorityScores = await fetchAuthorityScores(retrievedKnowledgeIds, organizationId);
  for (const knowledgeId of retrievedKnowledgeIds) {
    const authRows = await db.select({
      confidenceScore: knowledgeAuthoritySource.confidenceScore,
      levelNumber: authorityLevelMaster.levelNumber,
      role: knowledgeAuthoritySource.relationshipRole
    }).from(knowledgeAuthoritySource).innerJoin(authoritySource, eq(knowledgeAuthoritySource.authoritySourceId, authoritySource.id)).leftJoin(authorityLevelMaster, eq(authoritySource.authorityLevelId, authorityLevelMaster.id)).where(
      and(
        eq(knowledgeAuthoritySource.knowledgeId, knowledgeId),
        eq(knowledgeAuthoritySource.organizationId, organizationId)
      )
    );
    if (authRows.length === 0) {
      await recordAuthorityCheck(
        { sessionId, knowledgeId, checkResult: "NOT_APPLICABLE", confidenceScore: 0 },
        ctx
      );
    } else {
      const hasContradiction = authRows.some((r) => r.role === "CONTRADICTION");
      const score = resolveAuthorityConfidence(authRows[0].confidenceScore, authRows[0].levelNumber);
      await recordAuthorityCheck({
        sessionId,
        knowledgeId,
        checkResult: hasContradiction ? "CONFLICT" : "ALIGNED",
        confidenceScore: score
      }, ctx);
    }
  }
  await appendReasoningStep({
    sessionId,
    stepType: "VALIDATE",
    stepOrder,
    notes: `conflicts=${conflictCount} authorityChecks=${retrievedKnowledgeIds.length}`,
    durationMs: Date.now() - validateStart
  }, ctx);
  stepOrder++;
  const inferStart = Date.now();
  for (const row of diagRows) {
    const linkedRels = await db.select({ knowledgeId: knowledgeDiagnosisRelation.knowledgeId }).from(knowledgeDiagnosisRelation).where(eq(knowledgeDiagnosisRelation.diagnosisId, row.id));
    const linkedIds = new Set(linkedRels.map((r) => r.knowledgeId));
    const relScores = searchRes.items.filter((i) => linkedIds.has(i.knowledgeId)).map((i) => i.score);
    const avgRelevance = relScores.length > 0 ? relScores.reduce((a, b) => a + b, 0) / relScores.length : 0;
    const impactScore = Math.max(0, Math.min(1, row.impactScore ?? 0));
    const diagnosisScore = Math.max(0, Math.min(1, 0.5 * avgRelevance + 0.5 * impactScore));
    const corrRels = await db.select({ correctionId: diagnosisCorrectionRelation.correctionId }).from(diagnosisCorrectionRelation).where(eq(diagnosisCorrectionRelation.diagnosisId, row.id));
    matchedDiagnoses.push({
      diagnosisId: row.id,
      code: row.code,
      nameKo: row.nameKo ?? "",
      diagnosisScore,
      impactScore,
      correctionIds: corrRels.map((r) => r.correctionId)
    });
  }
  matchedDiagnoses.sort((a, b) => b.diagnosisScore - a.diagnosisScore);
  knowledgeUpdatedAts = searchRes.items.map(() => null);
  await appendReasoningStep({
    sessionId,
    stepType: "INFER",
    stepOrder,
    notes: `diagCandidates=${diagRows.length} matchedDiagnoses=${matchedDiagnoses.length}`,
    durationMs: Date.now() - inferStart
  }, ctx);
  stepOrder++;
  const synthesizeStart = Date.now();
  const modelName = await resolveModel(organizationId);
  let conclusionText = "";
  try {
    const completion = await openai.chat.completions.create({
      model: modelName,
      messages: [
        { role: "system", content: SYSTEM_PROMPT_DIAGNOSIS },
        { role: "user", content: buildDiagnosisPrompt(queryText, matchedDiagnoses, supportingEvidence.map((e) => e.content)) }
      ],
      max_tokens: 300,
      temperature: 0.3
    });
    conclusionText = completion.choices[0]?.message?.content?.trim() ?? "";
  } catch (e) {
    logger.warn(e, "SYNTHESIZE GPT failed, using fallback");
    conclusionText = matchedDiagnoses.length > 0 ? `\uC8FC\uC694 \uC9C4\uB2E8: ${matchedDiagnoses[0].nameKo}` : "\uC9C4\uB2E8 \uADFC\uAC70\uAC00 \uCDA9\uBD84\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.";
  }
  await appendReasoningStep({
    sessionId,
    stepType: "SYNTHESIZE",
    stepOrder,
    notes: `matchedDiagnoses=${matchedDiagnoses.length} conclusionLen=${conclusionText.length}`,
    durationMs: Date.now() - synthesizeStart
  }, ctx);
  const confidenceResult = weightedConfidenceCalculator.compute({
    relevanceScores,
    authorityScores,
    graphWeights: [],
    evidenceCount: supportingEvidence.length,
    conflictCount,
    knowledgeUpdatedAts
  });
  const { confidence: rawConfidenceScore, ...confidenceDetail } = confidenceResult;
  await recordReasoningConclusion({
    sessionId,
    conclusionText,
    confidenceScore: rawConfidenceScore,
    // DB에는 raw만 저장
    supportingCount: supportingEvidence.length,
    conflictCount,
    metaJson: { matchedDiagnoses, confidenceDetail }
  }, ctx);
  const durationMs = Date.now() - startMs;
  await completeReasoningSession(sessionId, organizationId, durationMs);
  const feedbackType = SESSION_TYPE_TO_FEEDBACK_TYPE["DIAGNOSIS"];
  const calibMeta = await getCalibrationMeta(organizationId, feedbackType, sessionId);
  const calibrated = buildCalibratedConfidenceResponse({
    rawScore: rawConfidenceScore,
    meta: calibMeta,
    organizationId,
    feedbackType,
    sessionId
  });
  return {
    sessionId,
    sessionType: "DIAGNOSIS",
    queryText,
    conclusionText,
    confidenceScore: calibrated.confidenceScore,
    rawConfidenceScore: calibrated.rawConfidenceScore,
    calibration: calibrated.calibration,
    confidenceDetail,
    matchedDiagnoses,
    supportingCount: supportingEvidence.length,
    conflictCount,
    stepCount: 5,
    durationMs
  };
}
