    organizationId: orgId,
    responseDraftId: draftId,
    knowledgeId: ev.knowledgeId ?? void 0,
    citationOrder: idx + 1,
    sourceName: ev.sourceName ?? void 0,
    authorityLevelNum: ev.authorityLevel ?? void 0,
    hasConflict: ev.evidenceType === "CONTRADICTING",
    conflictSummary: ev.conflictSummary ?? void 0,
