function buildKnowledgeWhereFrom(filters, startP) {
  const {
    publication_status = "PUBLISHED",
    knowledge_type,
    stroke,
    skill_category,
    level_scope,
    dta_axis,
    subject_scope,
    evidence_grade,
    search: search2
  } = filters;
  const conditions = [];
  const params = [];
  let p = startP;
  conditions.push(`k.publication_status = $${p++}`);
  params.push(publication_status);
  if (knowledge_type) {
    conditions.push(`k.knowledge_type = $${p++}`);
    params.push(knowledge_type);
  }
  if (stroke) {
    conditions.push(`k.stroke = $${p++}`);
    params.push(stroke);
  }
  if (skill_category) {
    conditions.push(`k.skill_category = $${p++}`);
    params.push(skill_category);
  }
  if (level_scope) {
    conditions.push(`k.level_scope = $${p++}`);
    params.push(level_scope);
  }
  if (dta_axis) {
    conditions.push(`k.dta_axis = $${p++}`);
    params.push(dta_axis);
  }
  if (subject_scope) {
    conditions.push(`k.subject_scope = $${p++}`);
    params.push(subject_scope);
  }
  if (evidence_grade) {
    conditions.push(`k.evidence_grade = $${p++}`);
    params.push(evidence_grade);
  }
  if (search2) {
    conditions.push(`(k.statement ILIKE $${p} OR k.normalized_statement ILIKE $${p})`);
    params.push(`%${search2}%`);
    p++;
  }
  const where = conditions.length > 0 ? `WHERE ${conditions.join(" AND ")}` : "";
  return { where, params, nextP: p };
}
var KNOWLEDGE_SELECT_COLS = `
  k.knowledge_uuid, k.global_canonical_uuid, k.statement, k.knowledge_type,
  k.stroke, k.skill_category, k.level_scope, k.dta_axis, k.subject_scope,
  k.evidence_grade, k.confidence, k.source_count, k.document_count, k.citation_count,
  k.version_no, k.publication_status, k.published_at, k.published_by
`.trim();
async function searchPublishedKnowledge(filters = {}) {
  const { schema = "kf", limit: limit2 = 20, offset = 0, ...rest } = filters;
  if (schema === "all") {
    const { where: w1, params: p1, nextP } = buildKnowledgeWhereFrom(rest, 1);
    const { where: w2, params: p2, nextP: nextP2 } = buildKnowledgeWhereFrom(rest, nextP);
    const allParams = [...p1, ...p2, limit2, offset];
    const [dataRes2, countKfRes, countDkfRes] = await Promise.all([
      pool.query(
        `SELECT * FROM (
           SELECT ${KNOWLEDGE_SELECT_COLS}, 'kf'::text AS source_schema
           FROM kf.knowledge k ${w1}
           UNION ALL
           SELECT ${KNOWLEDGE_SELECT_COLS}, 'diary_kf'::text AS source_schema
           FROM diary_kf.knowledge k ${w2}
         ) t
         ORDER BY published_at DESC
         LIMIT $${nextP2} OFFSET $${nextP2 + 1}`,
        allParams
      ),
      // count 쿼리는 조건이 동일하므로 w1/p1을 양쪽에 재사용
      pool.query(
        `SELECT COUNT(*) AS cnt FROM kf.knowledge k ${w1}`,
        p1
      ),
      pool.query(
        `SELECT COUNT(*) AS cnt FROM diary_kf.knowledge k ${w1}`,
        p1
      )
    ]);
    const total = parseInt(countKfRes.rows[0].cnt, 10) + parseInt(countDkfRes.rows[0].cnt, 10);
    return { items: dataRes2.rows, total };
  }
  const sch = schema;
  const kTbl = tbl(sch, "knowledge");
  const { where, params } = buildKnowledgeWhereFrom(rest, 1);
  const p = params.length + 1;
  const [dataRes, countRes] = await Promise.all([
    pool.query(
      `SELECT ${KNOWLEDGE_SELECT_COLS}, '${sch}'::text AS source_schema
       FROM ${kTbl} k ${where}
       ORDER BY k.published_at DESC
       LIMIT $${p} OFFSET $${p + 1}`,
      [...params, limit2, offset]
    ),
    pool.query(
      `SELECT COUNT(*) AS cnt FROM ${kTbl} k ${where}`,
      params
    )
  ]);
  return { items: dataRes.rows, total: parseInt(countRes.rows[0].cnt, 10) };
}
async function getPublishedKnowledgeByUuid(uuid2, schema = "kf") {
  const kTbl = tbl(schema, "knowledge");
  const res = await pool.query(
    `SELECT k.knowledge_uuid, k.global_canonical_uuid, k.statement, k.normalized_statement,
            k.knowledge_type, k.stroke, k.skill_category, k.level_scope, k.dta_axis,
            k.subject_scope, k.condition_scope, k.evidence_grade, k.confidence,
            k.source_count, k.document_count, k.citation_count, k.version_no,
            k.publication_status, k.published_at, k.published_by, k.updated_at, k.metadata_json,
            '${schema}'::text AS source_schema
     FROM ${kTbl} k WHERE k.knowledge_uuid=$1::uuid`,
    [uuid2]
  );
  if (res.rows.length === 0) return null;
  const row = res.rows[0];
  const meta = row.metadata_json ?? {};
  return {
    ...row,
    publish_hash: meta["publish_hash"] ?? null,
    publish_state: "CURRENT"
    // caller should compute if needed
  };
}
async function getKnowledgeSources(uuid2, schema = "kf") {
  const kTbl = tbl(schema, "knowledge");
  const kvTbl = tbl(schema, "knowledge_versions");
  const kslTbl = tbl(schema, "knowledge_source_links");
  const citTbl = tbl(schema, "citations");
  const ckTbl = tbl(schema, "canonical_knowledge");
  const docTbl = tbl(schema, "documents");
  const kRes = await pool.query(
    `SELECT knowledge_uuid, version_no FROM ${kTbl} WHERE knowledge_uuid=$1`,
    [uuid2]
  );
  if (kRes.rows.length === 0) return [];
  const vRes = await pool.query(
    `SELECT knowledge_version_uuid FROM ${kvTbl}
     WHERE knowledge_uuid=$1 ORDER BY version_no DESC LIMIT 1`,
    [uuid2]
  );
  if (vRes.rows.length === 0) return [];
  const versionUuid = vRes.rows[0].knowledge_version_uuid;
  const linksRes = await pool.query(
    `SELECT
       ksl.canonical_uuid,
       ksl.candidate_uuid,
       ksl.citation_uuid,
       ksl.chunk_uuid,
       ksl.document_uuid,
       c.source_quote,
       c.locator_json,
       ck.canonical_statement,
       ck.knowledge_type AS canonical_type,
       d.original_filename,
       d.understanding_json
     FROM ${kslTbl} ksl
     LEFT JOIN ${citTbl} c ON c.citation_uuid = ksl.citation_uuid
     LEFT JOIN ${ckTbl} ck ON ck.canonical_uuid = ksl.canonical_uuid
     LEFT JOIN ${docTbl} d ON d.id = ksl.document_uuid
     WHERE ksl.knowledge_version_uuid=$1
     ORDER BY ksl.canonical_uuid, ksl.citation_uuid`,
    [versionUuid]
  );
  return linksRes.rows.map((r) => ({
    canonical_uuid: r.canonical_uuid,
    canonical_statement: r.canonical_statement,
    candidate_uuid: r.candidate_uuid,
    citation_uuid: r.citation_uuid,
    chunk_uuid: r.chunk_uuid,
    document_uuid: r.document_uuid,
    source_quote: r.source_quote,
    locator_json: r.locator_json,
    document_title: r.understanding_json?.["title"] ?? r.original_filename,
    author: r.understanding_json?.["author"] ?? null,
    publication_year: r.understanding_json?.["publication_year"] ?? null,
    source_type: r.understanding_json?.["source_type"] ?? "GENERAL"
  }));
}
async function getKnowledgeVersions(uuid2, schema = "kf") {
  const kvTbl = tbl(schema, "knowledge_versions");
  const res = await pool.query(
    `SELECT knowledge_version_uuid, knowledge_uuid, global_canonical_uuid, version_no,
            statement, knowledge_type, evidence_grade, confidence,
            source_count, document_count, citation_count,
            change_type, change_reason, published_by, created_at
     FROM ${kvTbl}
     WHERE knowledge_uuid=$1 ORDER BY version_no ASC`,
    [uuid2]
  );
  return res.rows;
}
async function getKnowledgeVersionSnapshot(uuid2, versionNo, schema = "kf") {
  const kvTbl = tbl(schema, "knowledge_versions");
  const kslTbl = tbl(schema, "knowledge_source_links");
  const res = await pool.query(
    `SELECT kv.*, ksl.canonical_uuid, ksl.citation_uuid, ksl.document_uuid
     FROM ${kvTbl} kv
     LEFT JOIN ${kslTbl} ksl ON ksl.knowledge_version_uuid = kv.knowledge_version_uuid
     WHERE kv.knowledge_uuid=$1 AND kv.version_no=$2`,
    [uuid2, versionNo]
  );
  if (res.rows.length === 0) return null;
  const base2 = {
    knowledge_version_uuid: res.rows[0].knowledge_version_uuid,
    knowledge_uuid: res.rows[0].knowledge_uuid,
    global_canonical_uuid: res.rows[0].global_canonical_uuid,
    version_no: res.rows[0].version_no,
    statement: res.rows[0].statement,
    knowledge_type: res.rows[0].knowledge_type,
    evidence_grade: res.rows[0].evidence_grade,
    confidence: res.rows[0].confidence,
    change_type: res.rows[0].change_type,
    change_reason: res.rows[0].change_reason,
    published_by: res.rows[0].published_by,
    created_at: res.rows[0].created_at,
    snapshot_json: res.rows[0].snapshot_json
  };
  const linksRes = await pool.query(
    `SELECT canonical_uuid, candidate_uuid, citation_uuid, chunk_uuid, document_uuid
     FROM ${kslTbl} WHERE knowledge_version_uuid=$1`,
    [res.rows[0].knowledge_version_uuid]
  );
  return { ...base2, source_links: linksRes.rows };
}
async function getKnowledgeSummaryStats(schema = "kf") {
  if (schema === "all") {
    const [kfStats, dkfStats] = await Promise.all([
      getKnowledgeSummaryStats("kf"),
      getKnowledgeSummaryStats("diary_kf")
    ]);
    const kfGrades = kfStats["evidence_grades"] ?? {};
    const dkfGrades = dkfStats["evidence_grades"] ?? {};
    const allGrades = {};
    for (const [k, v] of Object.entries(kfGrades)) allGrades[k] = (allGrades[k] ?? 0) + v;
    for (const [k, v] of Object.entries(dkfGrades)) allGrades[k] = (allGrades[k] ?? 0) + v;
    return {
      published: kfStats["published"] + dkfStats["published"],
      retracted: kfStats["retracted"] + dkfStats["retracted"],
      archived: kfStats["archived"] + dkfStats["archived"],
      superseded: kfStats["superseded"] + dkfStats["superseded"],
      unpublished_approved: kfStats["unpublished_approved"] + dkfStats["unpublished_approved"],
      evidence_grades: allGrades
    };
  }
  const sch = schema;
  const kTbl = tbl(sch, "knowledge");
  const gckTbl = tbl(sch, "global_canonical_knowledge");
  const [statusRes, gradeRes, approvedUnpublishedRes] = await Promise.all([
    pool.query(
      `SELECT publication_status, COUNT(*) AS cnt FROM ${kTbl} GROUP BY publication_status`
    ),
    pool.query(
      `SELECT evidence_grade, COUNT(*) AS cnt FROM ${kTbl} WHERE publication_status='PUBLISHED' GROUP BY evidence_grade`
    ),
    pool.query(
      `SELECT COUNT(*) AS cnt FROM ${gckTbl} gc
       WHERE gc.status='APPROVED'
         AND NOT EXISTS (
           SELECT 1 FROM ${kTbl} k WHERE k.global_canonical_uuid=gc.global_canonical_uuid AND k.publication_status='PUBLISHED'
         )`
    )
  ]);
  const statusMap = {};
  for (const r of statusRes.rows) statusMap[r.publication_status] = parseInt(r.cnt, 10);
  const gradeMap = {};
  for (const r of gradeRes.rows) gradeMap[r.evidence_grade] = parseInt(r.cnt, 10);
  return {
    published: statusMap["PUBLISHED"] ?? 0,
    retracted: statusMap["RETRACTED"] ?? 0,
    archived: statusMap["ARCHIVED"] ?? 0,
    superseded: statusMap["SUPERSEDED"] ?? 0,
    unpublished_approved: parseInt(approvedUnpublishedRes.rows[0].cnt, 10),
    evidence_grades: gradeMap
  };
}

