function convertKrwToUsd(amountKrw, exchangeRateKrwPerUsd) {
  if (exchangeRateKrwPerUsd <= 0) {
    throw new Error("EVOLUTION_INVALID_EXCHANGE_RATE: must be > 0");
  }
  return amountKrw / exchangeRateKrwPerUsd;
}
async function createEvolutionRun(params) {
  const {
    targetDomain,
    enteredBudgetKrw,
    exchangeRateSnapshot,
    generatorVersion = "1",
    ruleVersion = "1",
    maxGenerationLevel = EVOLUTION_MAX_GENERATION_LEVEL
  } = params;
  const calculatedBudgetUsd = convertKrwToUsd(enteredBudgetKrw, exchangeRateSnapshot);
  const result = await pool.query(
    `INSERT INTO kf.evolution_runs (
       target_domain, generator_version, rule_version, max_generation_level,
       entered_budget_krw, exchange_rate_snapshot, calculated_budget_usd
     ) VALUES ($1, $2, $3, $4, $5, $6, $7)
     RETURNING *`,
    [
      targetDomain,
      generatorVersion,
      ruleVersion,
      maxGenerationLevel,
      enteredBudgetKrw,
      exchangeRateSnapshot,
      calculatedBudgetUsd
    ]
  );
  return mapRow(result.rows[0]);
}
async function getEvolutionRun(evolutionRunId) {
  const result = await pool.query(
    `SELECT * FROM kf.evolution_runs WHERE evolution_run_id = $1`,
    [evolutionRunId]
  );
  return result.rows[0] ? mapRow(result.rows[0]) : null;
}
async function updateEvolutionRunStatus(evolutionRunId, status, extra) {
  const now = /* @__PURE__ */ new Date();
  const isTerminal = TERMINAL_EVOLUTION_RUN_STATUSES.has(status);
  const isRunning = status === EVOLUTION_RUN_STATUS.RUNNING;
  const isPaused = status === EVOLUTION_RUN_STATUS.PAUSED;
  const result = await pool.query(
    `UPDATE kf.evolution_runs
        SET status = $2,
            stop_reason = COALESCE($3, stop_reason),
            started_at  = CASE WHEN $4 THEN COALESCE(started_at, $5::timestamptz) ELSE started_at END,
            paused_at   = CASE WHEN $6 THEN $5::timestamptz ELSE paused_at END,
            completed_at = CASE WHEN $7 THEN $5::timestamptz ELSE completed_at END,
            updated_at  = $5::timestamptz
      WHERE evolution_run_id = $1`,
    [
      evolutionRunId,
      status,
      extra?.stopReason ?? null,
      isRunning,
      now.toISOString(),
      isPaused,
      isTerminal
    ]
  );
  if ((result.rowCount ?? 0) === 0) {
    throw new Error(`EVOLUTION_RUN_NOT_FOUND: no row updated for run ${evolutionRunId}`);
  }
}
function mapRow(row) {
  return {
    evolutionRunId: row.evolution_run_id,
    targetDomain: row.target_domain,
    status: row.status,
    stopReason: row.stop_reason ?? null,
    generatorVersion: row.generator_version,
    ruleVersion: row.rule_version,
    maxGenerationLevel: Number(row.max_generation_level),
    enteredBudgetKrw: Number(row.entered_budget_krw),
    exchangeRateSnapshot: Number(row.exchange_rate_snapshot),
    calculatedBudgetUsd: Number(row.calculated_budget_usd),
    spentUsd: Number(row.spent_usd),
    callCount: Number(row.call_count),
    startedAt: row.started_at ? new Date(row.started_at) : null,
    pausedAt: row.paused_at ? new Date(row.paused_at) : null,
    completedAt: row.completed_at ? new Date(row.completed_at) : null,
    createdAt: new Date(row.created_at),
    updatedAt: new Date(row.updated_at)
  };
}

