// src/lib/kf/evolution/progress.ts
function buildProgressProjection(run, completedCycles, pendingDbOnly, pendingLlmRequired, pendingReview) {
  let sourceProcessed = 0;
  let candidatesDiscovered = 0;
  let dbOnlyProcessed = 0;
  let derivedCreated = 0;
  let duplicatesRejected = 0;
  let rejectCount = 0;
  let failed = 0;
  let maxGenerationSeen = 0;
  let lastCycleCompletedAt = null;
  for (const cycle of completedCycles) {
    sourceProcessed += cycle.inputKnowledgeCount;
    candidatesDiscovered += cycle.candidateCount;
    dbOnlyProcessed += cycle.dbOnlyCount;
    derivedCreated += cycle.newValidKnowledgeCount;
    duplicatesRejected += cycle.duplicateCount;
    rejectCount += cycle.rejectCount;
    failed += cycle.failedCount;
    if (cycle.completedAt) {
      if (!lastCycleCompletedAt || cycle.completedAt > lastCycleCompletedAt) {
        lastCycleCompletedAt = cycle.completedAt;
      }
    }
    maxGenerationSeen = Math.max(maxGenerationSeen, cycle.cycleNo);
  }
  const budgetTotalUsd = run.calculatedBudgetUsd;
  const budgetSpentUsd = run.spentUsd;
  const budgetRemainingUsd = Math.max(0, budgetTotalUsd - budgetSpentUsd);
  return {
    evolutionRunId: run.evolutionRunId,
    status: run.status,
    targetDomain: run.targetDomain,
    currentCycleNo: completedCycles.length,
    totalCyclesCompleted: completedCycles.length,
    sourceProcessed,
    candidatesDiscovered,
    dbOnlyProcessed,
    llmPending: pendingLlmRequired,
    reviewPending: pendingReview,
    derivedCreated,
    duplicatesRejected,
    qualityRejected: rejectCount,
    failed,
    generationLevel: maxGenerationSeen,
    maxGenerationLevel: run.maxGenerationLevel,
    budgetSpentUsd,
    budgetRemainingUsd,
    budgetTotalUsd,
    callCount: run.callCount,
    startedAt: run.startedAt,
    lastCycleCompletedAt,
    estimatedAt: (/* @__PURE__ */ new Date()).toISOString()
  };
}

