function buildCostPreview(opts) {
  const maxEstimatedTotalUsd = opts.llmCandidateEstimate * opts.avgCostPerCallUsd;
  const maxEstimatedTotalKrw = Math.round(maxEstimatedTotalUsd * opts.exchangeRateKrwPerUsd);
  const likelyBudgetExhausted = maxEstimatedTotalUsd > opts.userBudgetCeilingUsd;
  return {
    llmCandidateEstimate: opts.llmCandidateEstimate,
    avgCostPerCallUsd: opts.avgCostPerCallUsd,
    maxEstimatedTotalUsd,
    maxEstimatedTotalKrw,
    userBudgetCeilingUsd: opts.userBudgetCeilingUsd,
    likelyBudgetExhausted,
    disclaimer: "MAXIMUM_ESTIMATE_NOT_ACTUAL"
  };
}

