router21.patch("/canonical-knowledge/:canonical_uuid", async (req, res) => {
  const { canonical_uuid } = req.params;
  const existing = await pool.query(
    `SELECT canonical_uuid FROM kf.canonical_knowledge WHERE canonical_uuid = $1`,
    [canonical_uuid]
  );
  if (existing.rows.length === 0) {
    res.status(404).json({ error: "NOT_FOUND", message: "Canonical\uC744 \uCC3E\uC744 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4." });
    return;
  }
  const allowed = [
    "canonical_statement",
    "knowledge_type",
    "stroke",
    "skill_category",
    "level_scope",
    "dta_axis",
    "subject_scope",
    "condition_scope",
    "status",
    "metadata_json"
  ];
  const updates = [];
  const params = [];
  for (const field of allowed) {
    if (field in req.body) {
      params.push(req.body[field]);
      updates.push(`${field} = $${params.length}`);
    }
  }
  if (updates.length === 0) {
    res.status(400).json({ error: "NO_UPDATE_FIELDS", message: "\uC218\uC815\uD560 \uD544\uB4DC\uAC00 \uC5C6\uC2B5\uB2C8\uB2E4." });
    return;
  }
  params.push(canonical_uuid);
  const r = await pool.query(
    `UPDATE kf.canonical_knowledge
     SET ${updates.join(", ")}, updated_at = NOW()
     WHERE canonical_uuid = $${params.length}
     RETURNING *`,
    params
  );
  res.json(r.rows[0]);
});
