router21.post("/canonical-knowledge/:canonical_uuid/link-candidate", async (req, res) => {
  const { canonical_uuid } = req.params;
  const { candidate_uuid } = req.body ?? {};
  if (!candidate_uuid) {
    res.status(400).json({ error: "MISSING_FIELD", message: "candidate_uuid\uAC00 \uD544\uC694\uD569\uB2C8\uB2E4." });
    return;
  }
  const canonicalCheck = await pool.query(
    `SELECT canonical_uuid FROM kf.canonical_knowledge WHERE canonical_uuid = $1`,
    [canonical_uuid]
  );
  if (canonicalCheck.rows.length === 0) {
    res.status(404).json({ error: "NOT_FOUND", message: "Canonical\uC744 \uCC3E\uC744 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4." });
    return;
  }
  const draftCheck = await pool.query(
    `SELECT d.candidate_uuid FROM kf.knowledge_candidate_drafts d
     JOIN kf.citations c ON c.candidate_uuid = d.candidate_uuid
     WHERE d.candidate_uuid = $1`,
    [candidate_uuid]
  );
  if (draftCheck.rows.length === 0) {
    res.status(400).json({
      error: "NO_CITATION",
      message: "Citation\uC774 \uC5C6\uB294 Candidate\uB294 \uC5F0\uACB0\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4."
    });
    return;
  }
  const existingLink = await pool.query(
    `SELECT canonical_uuid FROM kf.canonical_candidate_links WHERE candidate_uuid = $1`,
    [candidate_uuid]
  );
  if (existingLink.rows.length > 0) {
    res.status(409).json({
      error: "ALREADY_LINKED",
      message: "\uC774\uBBF8 \uB2E4\uB978 Canonical\uC5D0 \uC5F0\uACB0\uB41C Candidate\uC785\uB2C8\uB2E4.",
      canonical_uuid: existingLink.rows[0].canonical_uuid
    });
    return;
  }
  await pool.query(
    `INSERT INTO kf.canonical_candidate_links
       (canonical_uuid, candidate_uuid, match_type, created_at)
     VALUES ($1, $2, 'MANUAL', NOW())
     ON CONFLICT DO NOTHING`,
    [canonical_uuid, candidate_uuid]
  );
  res.status(201).json({ canonical_uuid, candidate_uuid, match_type: "MANUAL" });
});
router21.delete(
  "/canonical-knowledge/:canonical_uuid/candidates/:candidate_uuid",
  async (req, res) => {
    const { canonical_uuid, candidate_uuid } = req.params;
    const linkCheck = await pool.query(
      `SELECT link_uuid FROM kf.canonical_candidate_links
       WHERE canonical_uuid = $1 AND candidate_uuid = $2`,
      [canonical_uuid, candidate_uuid]
    );
    if (linkCheck.rows.length === 0) {
      res.status(404).json({ error: "NOT_FOUND", message: "\uC5F0\uACB0\uC744 \uCC3E\uC744 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4." });
      return;
    }
    await pool.query(
      `DELETE FROM kf.canonical_candidate_links
       WHERE canonical_uuid = $1 AND candidate_uuid = $2`,
      [canonical_uuid, candidate_uuid]
    );
    const remaining = await pool.query(
      `SELECT COUNT(*) AS cnt FROM kf.canonical_candidate_links WHERE canonical_uuid = $1`,
      [canonical_uuid]
    );
    const remainingCount = parseInt(remaining.rows[0].cnt, 10);
    if (remainingCount === 0) {
      await pool.query(
        `UPDATE kf.canonical_knowledge
         SET status = 'REVIEW_REQUIRED', updated_at = NOW()
         WHERE canonical_uuid = $1`,
        [canonical_uuid]
      );
    }
    res.json({
      canonical_uuid,
      candidate_uuid,
      remaining_candidates: remainingCount,
      canonical_status: remainingCount === 0 ? "REVIEW_REQUIRED" : void 0
    });
  }
);
router21.get("/documents/:id/chunks", async (req, res) => {
  const { id } = req.params;
  const page = Math.max(1, parseInt(String(req.query.page ?? "1"), 10));
  const limit2 = Math.min(200, Math.max(1, parseInt(String(req.query.limit ?? "50"), 10)));
  const offset = (page - 1) * limit2;
  const heading2 = typeof req.query.heading === "string" ? req.query.heading : null;
  const pageNum = typeof req.query.page_num === "string" ? parseInt(req.query.page_num, 10) : null;
  const docCheck = await pool.query(
    `SELECT id FROM kf.documents WHERE id = $1`,
    [id]
  );
  if (docCheck.rows.length === 0) {
    res.status(404).json({ error: "NOT_FOUND", message: "\uBB38\uC11C\uB97C \uCC3E\uC744 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4." });
    return;
  }
  const conditions = ["document_id = $1"];
  const params = [id];
  if (heading2) {
    params.push(`%${heading2}%`);
    conditions.push(`heading_path_json::text ILIKE $${params.length}`);
  }
  if (pageNum !== null && !isNaN(pageNum)) {
    params.push(pageNum);
    conditions.push(`(page_start <= $${params.length} AND page_end >= $${params.length})`);
  }
  const where = `WHERE ${conditions.join(" AND ")}`;
  const [chunksResult, countResult] = await Promise.all([
    pool.query(
      `SELECT id, chunk_uuid, document_id, chunk_index,
              title, start_block_uuid, end_block_uuid,
              block_count, character_count,
              page_start, page_end, heading_path_json,
              created_at, updated_at
       FROM kf.document_chunks
       ${where}
       ORDER BY chunk_index ASC
       LIMIT $${params.length + 1} OFFSET $${params.length + 2}`,
      [...params, limit2, offset]
    ),
    pool.query(`SELECT COUNT(*) FROM kf.document_chunks ${where}`, params)
  ]);
  res.json({
    chunks: chunksResult.rows,
    total: parseInt(countResult.rows[0].count, 10),
    page,
    limit: limit2
  });
});
