// src/lib/core-ai/adapters/CostAwareGPTAdapter.ts
init_errors3();
init_cost_aware_wrapper();
init_types2();
var CORE_AI_PRICE_VERSION = 2;
var CostAwareGPTAdapter = class {
  constructor(inner, pool2, serviceDomain = "CORE_AI_REASONING") {
    this.inner = inner;
    this.serviceDomain = serviceDomain;
    this.wrapper = new CostAwareWrapper(pool2);
  }
  providerId = "gpt";
  wrapper;
  supports(request, context) {
    return this.inner.supports(request, context);
  }
  async generate(request) {
    const model = request.model ?? "gpt-5.6-luna";
    const maxIn = (request.systemPrompt.length + request.userPrompt.length) / 4;
    const maxOut = request.maxTokens ?? 1024;
    const estimatedCost = Math.max(1e-4, (maxIn * 3 + maxOut * 12) / 1e6);
    const ctx = {
      requestId: request.requestId,
      taskType: "AI_REASONING",
      featureId: "CORE_AI_RESPONSE",
      provider: "OPENAI",
      model,
      serviceDomain: this.serviceDomain,
      normalizedInputHash: "",
      priceVersion: CORE_AI_PRICE_VERSION,
      billingType: "TOKEN"
    };
    const estimate = {
      estimatedCostUsd: estimatedCost,
      reservedCostUsd: estimatedCost,
      billingType: "TOKEN",
      maxInputTokens: Math.ceil(maxIn),
      maxOutputTokens: maxOut
    };
    let result;
    try {
      await this.wrapper.call(ctx, estimate, async () => {
        result = await this.inner.generate(request);
        const inTok = result.usage?.promptTokens ?? 0;
        const outTok = result.usage?.completionTokens ?? 0;
        return {
          value: result,
          usage: { billingType: "TOKEN", inputTokens: inTok, outputTokens: outTok },
          latencyMs: result.latencyMs ?? 0
        };
      });
    } catch (err2) {
      if (err2 instanceof ProviderCallError) {
        throw new LLMProviderError(
          `Budget blocked: ${err2.kind}`,
          this.providerId,
          request.requestId,
          model
        );
      }
      throw err2;
    }
    return result;
  }
  async health() {
    return this.inner.health();
  }
  estimateCost(request) {
    return this.inner.estimateCost(request);
  }
};

