// src/lib/diary-v2/observation-builder/ObservationBuilder.ts
function segmentToOrderedSentences(seg) {
  const len = Math.min(seg.sentences.length, seg.source_order.length);
  const result = [];
  for (let i = 0; i < len; i++) {
    result.push({
      text: seg.sentences[i],
      source_order: seg.source_order[i]
    });
  }
  return result;
}
function sortBySourceOrder(items) {
  return [...items].sort((a, b) => a.source_order - b.source_order);
}
function buildObservation(items) {
  const sorted = sortBySourceOrder(items);
  const sentences = sorted.map((s) => s.text);
  const source_order = sorted.map((s) => s.source_order);
  const text7 = sentences.join(" ");
  return { sentences, text: text7, source_order };
}
function emptyObservation() {
  return { sentences: [], text: "", source_order: [] };
}
function buildObservations(input) {
  const { parsed, students } = input;
  const commonItems = [];
  for (const seg of parsed.common) {
    commonItems.push(...segmentToOrderedSentences(seg));
  }
  const common = buildObservation(commonItems);
  const studentBuckets = /* @__PURE__ */ new Map();
  const unresolvedList = [];
  for (const seg of parsed.students) {
    const rawName = seg.raw_name ?? "";
    const matchResult = matchName({
      raw_name: rawName,
      students
    });
    const segSentences = segmentToOrderedSentences(seg);
    if (matchResult.status === "MATCHED") {
      const ref = matchResult.student_ref;
      const bucket = studentBuckets.get(ref) ?? [];
      bucket.push(...segSentences);
      studentBuckets.set(ref, bucket);
    } else {
      let reason;
      if (matchResult.status === "AMBIGUOUS") {
        reason = "NAME_AMBIGUOUS";
      } else if (matchResult.reason === "INVALID_INPUT") {
        reason = "INVALID_NAME_INPUT";
      } else {
        reason = "NAME_UNMATCHED";
      }
      const obs = buildObservation(segSentences);
      const unresolved = {
        ...obs,
        reason,
        match_status: matchResult.status === "AMBIGUOUS" ? "AMBIGUOUS" : "UNMATCHED",
        match_reason: matchResult.reason
      };
      unresolvedList.push(unresolved);
    }
  }
  for (const seg of parsed.unresolved) {
    const segSentences = segmentToOrderedSentences(seg);
    const obs = buildObservation(segSentences);
    const unresolved = {
      ...obs,
      reason: "PARSER_UNRESOLVED"
    };
    unresolvedList.push(unresolved);
  }
  const outputStudents = students.map((s) => {
    const bucket = studentBuckets.get(s.ref);
    if (bucket && bucket.length > 0) {
      const obs = buildObservation(bucket);
      return {
        student_ref: s.ref,
        ...obs
      };
    }
    return {
      student_ref: s.ref,
      ...emptyObservation()
    };
  });
  return {
    common,
    students: outputStudents,
    unresolved: unresolvedList
  };
}

// src/lib/diary-v2/orchestrator/DiaryOrchestrator.ts
function buildStudentsArray(input) {
  const nameMap = resolveStudentNames(input.request.context);
  return input.request.context.student_refs.filter((ref) => nameMap[ref] !== void 0).map((ref) => ({ ref, name: nameMap[ref] }));
}
async function runDiaryOrchestrator(input, deps) {
  const selectedMode = input.mode ?? getDiaryPipelineMode();
  const parseStateFn = deps.parseState ?? parseDiaryState;
  const buildObsFn = deps.buildObservations ?? buildObservations;
  if (selectedMode === "parser_v1") {
    const students = buildStudentsArray(input);
    const rawText = input.request.input.text;
    const parsed = parseStateFn({ text: rawText, students });
    const observations = buildObsFn({ parsed, students });
    const pipelineResult = {
      students,
      parsed,
      observations
    };
    return {
      mode: "parser_v1",
      status: "PIPELINE_READY",
      result: pipelineResult
    };
  }
  if (selectedMode === "grounded_v1") {
    if (!deps.groundedGenerate) {
      return {
        mode: "grounded_v1",
        status: "NOT_IMPLEMENTED",
        error: {
          code: "DIARY_PIPELINE_NOT_IMPLEMENTED",
          message: "grounded_v1 \uD30C\uC774\uD504\uB77C\uC778\uC740 \uC544\uC9C1 \uAD6C\uD604\uB418\uC9C0 \uC54A\uC558\uC2B5\uB2C8\uB2E4. STEP 6/7 \uC644\uB8CC \uD6C4 \uD65C\uC131\uD654\uB429\uB2C8\uB2E4."
        }
      };
    }
    const result = await deps.groundedGenerate(input.request);
    return {
      mode: "grounded_v1",
      status: "COMPLETED",
      result
    };
  }
  const legacyResult = await deps.legacyGenerate(input.request);
  return {
    mode: "legacy",
    status: "COMPLETED",
    result: legacyResult
  };
}

