        source: "RULE",
        matched_definition_fields: [],
        matched_behavior_refs: [],
        rationale_codes: ["DISCRIMINATION_GATE_BLOCKED"],
        contradictions_detected: false,
        ambiguity_detected: false,
        observation_relation: "NEUTRAL"
