        "\uD63C\uC790",
        "\uBA3C\uC800",
        "\uC2DC\uD0A4\uC9C0 \uC54A\uC558\uB294\uB370",
        "\uAD50\uC0AC\uAC00 \uB9D0\uD558\uAE30 \uC804\uC5D0",
        "\uC218\uC5C5\uC774 \uB05D\uB09C \uB4A4",
        "\uC885\uB8CC \uD6C4",
        "\uC218\uC5C5 \uC774\uD6C4",
        "\uC54C\uC544\uC11C",
