function formatAllowedClaims(claims) {
  const allowed = claims.filter((c) => c.allowed_for_parent_output);
  if (allowed.length === 0) return "(\uD5C8\uC6A9\uB41C Claim\uC774 \uC5C6\uC2B5\uB2C8\uB2E4.)";
  return allowed.map(
    (c) => `[${c.claim_id}] TYPE=${c.claim_type} GROUNDING=${c.grounding_level} CONFIDENCE=${c.confidence.toFixed(2)}
  FACT="${c.canonical_fact}"`
  ).join("\n");
}
function deriveStabilityState(confidence, evidenceCount) {
  if (evidenceCount === 0) return "\uCC98\uC74C \uACBD\uD5D8 \uC911";
  if (evidenceCount === 1 && confidence < 0.5) return "\uC774\uD574\uB294 \uC2DC\uC791\uB428";
  if (evidenceCount === 1 && confidence < 0.7) return "\uAD50\uC0AC \uB3C4\uC6C0\uACFC \uD568\uAED8 \uC218\uD589 \uAC00\uB2A5";
  if (evidenceCount >= 2 && confidence < 0.6) return "\uBC18\uBCF5\uD558\uBA74 \uC218\uD589 \uAC00\uB2A5";
  if (evidenceCount >= 2 && confidence < 0.75) return "\uB3C5\uB9BD \uC218\uD589\uC774 \uB098\uD0C0\uB0A8";
  if (evidenceCount >= 3 && confidence < 0.85) return "\uC5EC\uB7EC \uC218\uC5C5\uC5D0\uC11C \uBC18\uBCF5\uB428";
  if (evidenceCount >= 3 && confidence < 0.92) return "\uC0C1\uD669\uC774 \uBC14\uB00C\uBA74 \uC544\uC9C1 \uBD88\uC548\uC815";
  return "\uC548\uC815\uC801\uC73C\uB85C \uC720\uC9C0\uB428";
}
