    const longitudinalHint = hasLongitudinalPair ? '\n  \u203B [\uC774\uC804]/[\uD604\uC7AC] \uC7A5\uBA74\uC774 \uC788\uC744 \uB54C\uB9CC "\uC774\uC804\uC5D0\uB294 ~ \uCD5C\uADFC\uC5D0\uB294 ~" \uBE44\uAD50 \uD45C\uD604 \uC0AC\uC6A9. \uB450 \uAD00\uCC30 \uBAA8\uB450 \uC788\uC5B4\uC57C \uD568.' : "";
