// src/lib/growth-report/composition/GroundingValidator.ts
var LONGITUDINAL_WORDING_PATTERNS = [
  /좋아졌|늘었|나아졌|향상됐|발전했|성장했|강해졌|안정됐|확장됐/,
  /이전보다|지난\s*\S+보다|전월보다|저번보다/,
  /점점|갈수록|꾸준히\s+좋아|지속적으로\s+향상/
];
var SWIMMING_OVERREACH_PATTERNS = [
  /완벽한\s*수영|선수급|타고난\s*재능|전문가급/,
  /물리학적|생체역학|역학적\s*분석|DTA/
];
function sentencesFrom(text7) {
  if (!text7) return [];
  return text7.split(/[.!?。]/g).map((s) => s.trim()).filter((s) => s.length > 5);
}
function validateGrounding(draft, pkg) {
  const claimMap = new Map(
    pkg.claim_registry.map((c) => [c.claim_id, c])
  );
  const hasLongitudinalClaims = pkg.claim_registry.some((c) => c.claim_type === "LONGITUDINAL_CHANGE");
  const hasSwimmingClaims = pkg.claim_registry.some(
    (c) => c.claim_type === "SWIMMING_PROGRESS" || c.claim_type === "SWIMMING_STRENGTH"
  );
  const unsupported = [];
  let totalSentences = 0;
  function validateSection(sectionId, text7, claimIds) {
    if (!text7) return;
    const sentences = sentencesFrom(text7);
    totalSentences += sentences.length;
    for (const cid of claimIds) {
      if (!claimMap.has(cid)) {
        unsupported.push({
          section_id: sectionId,
          sentence: `claim_id \uCC38\uC870: ${cid}`,
          reason_codes: ["UNKNOWN_CLAIM_ID"]
        });
      }
    }
    for (const cid of claimIds) {
      const claim = claimMap.get(cid);
      if (claim && !claim.allowed_for_parent_output) {
        unsupported.push({
          section_id: sectionId,
          sentence: `blocked claim \uC0AC\uC6A9: ${cid}`,
          reason_codes: ["CLAIM_NOT_ALLOWED_FOR_PARENT"]
        });
      }
    }
    for (const cid of claimIds) {
      const claim = claimMap.get(cid);
      if (claim && claim.evidence_ids.length === 0) {
        unsupported.push({
          section_id: sectionId,
          sentence: `evidence \uC5C6\uB294 claim: ${cid}`,
          reason_codes: ["NO_EVIDENCE_TRACE"]
        });
      }
    }
    if (!hasLongitudinalClaims) {
      for (const sentence of sentences) {
        for (const pattern of LONGITUDINAL_WORDING_PATTERNS) {
          if (pattern.test(sentence)) {
            unsupported.push({
              section_id: sectionId,
              sentence,
              reason_codes: ["LONGITUDINAL_WORDING_WITHOUT_DATA"]
            });
            break;
          }
        }
      }
    }
    if (!hasSwimmingClaims) {
      for (const sentence of sentences) {
        for (const pattern of SWIMMING_OVERREACH_PATTERNS) {
          if (pattern.test(sentence)) {
            unsupported.push({
              section_id: sectionId,
              sentence,
              reason_codes: ["SWIMMING_OVERREACH_WITHOUT_VERIFIED_DATA"]
            });
            break;
          }
        }
      }
    }
    if (sectionId === "summary" && claimIds.length === 0 && text7.length > 5) {
      unsupported.push({
        section_id: sectionId,
        sentence: text7.slice(0, 80),
        reason_codes: ["SUMMARY_NO_CLAIM_TRACE"]
      });
    }
  }
  validateSection("summary", draft.summary_text, draft.summary_claim_ids);
  const sectionIds = [
    "core_growth",
    "swimming_progress",
    "behavioral_strengths",
    "longitudinal_comparison",
    "success_conditions",
    "parent_support",
    "teacher_guidance",
    "next_growth_direction"
  ];
  for (const sid of sectionIds) {
    const sec = draft.sections[sid];
    if (sec) {
      validateSection(sid, sec.text, sec.claim_ids);
    }
  }
  validateSection("sns", draft.sns_summary.headline, draft.sns_summary.supporting_claim_ids);
  for (const pt of draft.sns_summary.key_points) {
    totalSentences++;
  }
  const rejectedSentences = unsupported.length;
  const groundedSentences = Math.max(0, totalSentences - rejectedSentences);
  const groundingScore = totalSentences > 0 ? groundedSentences / totalSentences : 1;
  let status;
  if (unsupported.length === 0) {
    status = "PASS";
  } else if (groundingScore >= 0.8) {
    status = "REVISED_PASS";
  } else {
    status = "FAIL";
  }
  return {
    status,
    total_sentences: totalSentences,
    grounded_sentences: groundedSentences,
    rejected_sentences: rejectedSentences,
    unsupported_claims: unsupported,
    grounding_score: groundingScore,
    validator_version: GROUNDING_VALIDATOR_VERSION
  };
}
function collectGroundingIssues(result) {
  return result.unsupported_claims.map(
    (u) => `[${u.section_id}] ${u.reason_codes.join(",")} \u2014 "${u.sentence.slice(0, 60)}"`
  );
}

